import { referenceTheme } from './generated'
import { builtinTokens } from '../../generated/tokens'
import { contrastRatio } from '../../theme/contrast'
import type { ResolvedTheme, ThemeRole } from '../../theme/types'

interface Slot {
  readonly key: string
  readonly role: ThemeRole
  readonly raw: string
  readonly background?: string
  readonly minimum?: number
}
const slots: Readonly<Record<string, Slot>> = referenceTheme.slots
export interface ReferenceStyleProjection {
  readonly colors: Readonly<Record<string, string>>
  readonly repairs: readonly {
    readonly slot: string
    readonly original: string
    readonly effective: string
  }[]
}
function composite(raw: string, background?: string): string {
  let hex = raw.slice(1)
  if (hex.length < 5) hex = [...hex].map((char) => char + char).join('')
  if (hex.length === 6) return '#' + hex.toUpperCase()
  if (hex.length !== 8 || !background) throw Error('Unbound reference alpha')
  const alpha = parseInt(hex.slice(6), 16) / 255
  return (
    '#' +
    [0, 2, 4]
      .map((offset) =>
        Math.round(
          parseInt(hex.slice(offset, offset + 2), 16) * alpha +
            parseInt(background.slice(offset + 1, offset + 3), 16) * (1 - alpha),
        )
          .toString(16)
          .padStart(2, '0'),
      )
      .join('')
      .toUpperCase()
  )
}
/** First-party view projection, after the existing resolver; it never selects or persists a theme. */
export function projectReferenceStyles(snapshot: ResolvedTheme): ReferenceStyleProjection {
  if (snapshot.id !== referenceTheme.id || snapshot.forcedColors) return { colors: {}, repairs: [] }
  const colors: Record<string, string> = {},
    active = new Set<string>()
  const repairs: { slot: string; original: string; effective: string }[] = []
  const resolve = (name: string): string => {
    if (colors[name]) return colors[name]
    if (active.has(name) || !Object.hasOwn(slots, name))
      throw Error('Invalid reference style dependency')
    active.add(name)
    const slot = slots[name],
      background = slot.background ? resolve(slot.background) : undefined
    const roleChanged = snapshot.colors[slot.role] !== referenceTheme.descriptor.colors[slot.role]
    let color = roleChanged ? snapshot.colors[slot.role] : composite(slot.raw, background)
    if (background && slot.minimum && contrastRatio(color, background) < slot.minimum) {
      const original = color
      const replacement = [
        snapshot.colors[slot.role],
        builtinTokens.themes.dark[slot.role],
        builtinTokens.themes.dark['text.primary'],
        builtinTokens.themes.light['text.primary'],
      ].find((candidate) => contrastRatio(candidate, background) >= slot.minimum!)
      if (!replacement) throw Error('Reference style contrast cannot be established: ' + name)
      color = replacement
      repairs.push({ slot: name, original, effective: color })
    }
    active.delete(name)
    colors[name] = color
    return color
  }
  for (const name of Object.keys(slots)) resolve(name)
  return { colors: Object.freeze(colors), repairs: Object.freeze(repairs) }
}

export function applyReferencePreset(root: HTMLElement, snapshot: ResolvedTheme): void {
  if (snapshot.id !== referenceTheme.id || snapshot.forcedColors) {
    if (root.dataset.fradeReference === 'vscode-dark-2026') {
      root.removeAttribute('data-frade-reference')
      for (const name of Object.keys(slots)) root.style.removeProperty('--frade-vscode-' + name)
    }
    return
  }
  const projection = projectReferenceStyles(snapshot)
  for (const [name, color] of Object.entries(projection.colors))
    root.style.setProperty('--frade-vscode-' + name, color)
  root.dataset.fradeReference = 'vscode-dark-2026'
}

import { test } from 'node:test'
import assert from 'node:assert/strict'
import {
  mkdtemp,
  mkdir,
  copyFile,
  readFile,
  writeFile,
  realpath,
  stat,
  rm,
  unlink,
} from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { dirname, join, resolve, relative } from 'node:path'
import { spawnSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import {
  root,
  generatedPath,
  referenceDirectory,
  checkReferenceFiles,
  compositeColor,
  parseSourceClosure,
} from '../../scripts/ui/vscode-dark-2026.mjs'
import { checkFeatureColors, featureRoots } from '../../scripts/ui/colors.mjs'

const digest = (bytes) => createHash('sha256').update(bytes).digest('hex')
async function fixture(run) {
  const parent = await realpath(tmpdir()),
    directory = await mkdtemp(join(parent, 'frade-vscode-contract-'))
  const owner = await stat(directory, { bigint: true })
  const put = async (name, value) => {
    const target = resolve(directory, name)
    assert(!relative(directory, target).startsWith('..'))
    await mkdir(dirname(target), { recursive: true })
    await writeFile(target, value)
  }
  try {
    for (const name of [
      '2026-dark.json',
      'dark_modern.json',
      'dark_plus.json',
      'dark_vs.json',
      'LICENSE.txt',
    ]) {
      const file = referenceDirectory + '/upstream/' + name
      await put(file, await readFile(resolve(root, file)))
    }
    for (const file of [
      referenceDirectory + '/.gitattributes',
      generatedPath,
      'packages/ui-workspace/tokens/tokens.json',
    ])
      await put(file, await readFile(resolve(root, file)))
    await run({ directory, put })
  } finally {
    const actual = await realpath(directory),
      current = await stat(actual, { bigint: true })
    assert.equal(dirname(actual), parent)
    assert(actual.startsWith(join(parent, 'frade-vscode-contract-')))
    assert.equal(current.ino, owner.ino)
    assert.equal(current.dev, owner.dev)
    await rm(actual, { recursive: true })
  }
}
function git(cwd, args) {
  const result = spawnSync(
    'git',
    [
      '-c',
      'core.longpaths=true',
      '-c',
      'maintenance.auto=false',
      '-c',
      'gc.auto=0',
      '-c',
      'commit.gpgSign=false',
      ...args,
    ],
    { cwd, encoding: 'utf8', windowsHide: true, timeout: 30000 },
  )
  assert.equal(result.status, 0, result.stderr + result.stdout)
  return result.stdout
}

test('VS2026 positive source-bound generation passes without rewriting files', async () => {
  const before = digest(await readFile(resolve(root, generatedPath)))
  assert.equal((await checkReferenceFiles()).status, 'PASS')
  assert.equal(digest(await readFile(resolve(root, generatedPath))), before)
})

test('VS2026 generated drift and original-source drift are rejected', async () =>
  fixture(async ({ directory, put }) => {
    assert.equal((await checkReferenceFiles(directory)).status, 'PASS')
    const original = await readFile(resolve(directory, generatedPath))
    await put(generatedPath, Buffer.concat([original, Buffer.from('\n// isolated drift\n')]))
    assert.deepEqual((await checkReferenceFiles(directory)).errors, ['REFERENCE_GENERATED_DRIFT'])
    await put(generatedPath, original)
    const source = referenceDirectory + '/upstream/2026-dark.json'
    await put(
      source,
      Buffer.concat([await readFile(resolve(directory, source)), Buffer.from('\n')]),
    )
    assert.match((await checkReferenceFiles(directory)).errors.join(), /REFERENCE_SOURCE_DRIFT/)
  }))

test('VS2026 missing inherited source fails without fallback', async () =>
  fixture(async ({ directory }) => {
    await unlink(resolve(directory, referenceDirectory, 'upstream/dark_plus.json'))
    assert.equal((await checkReferenceFiles(directory)).status, 'FAIL')
  }))

test('VS2026 JSONC include inheritance, cycles and traversal are explicit', () => {
  const files = {
    '2026-dark.json':
      '{ "include":"./dark_modern.json", "colors":{"sample":"#121314",}, /* source comment */ }',
    'dark_modern.json': '{ "include":"./dark_plus.json", "colors":{"sample":"#222222"} }',
    'dark_plus.json':
      '{ "include":"./dark_vs.json", "tokenColors":[{"scope":"test","settings":{"foreground":"#abcdef"}}] }',
    'dark_vs.json': '{ "colors":{"base":"#010203"} }',
  }
  const parsed = parseSourceClosure(files)
  assert.equal(parsed.colors.sample, '#121314')
  assert.equal(parsed.colors.base, '#010203')
  assert.equal(parsed.tokenColors.length, 1)
  assert.throws(
    () => parseSourceClosure({ ...files, '2026-dark.json': '{"include":"../private.json"}' }),
    /UNSAFE_REFERENCE_INCLUDE/,
  )
  assert.throws(
    () => parseSourceClosure({ ...files, 'dark_vs.json': '{"include":"./2026-dark.json"}' }),
    /CYCLIC_REFERENCE_INCLUDE/,
  )
})

test('VS2026 sRGB alpha composition uses the real backdrop', () => {
  assert.equal(compositeColor('#FFFFFF22', '#191A1B'), '#383939')
  assert.equal(compositeColor('#0000', '#191A1B'), '#191A1B')
  assert.equal(compositeColor('#abc'), '#AABBCC')
  assert.throws(() => compositeColor('#ffffff22'), /UNBOUND_REFERENCE_ALPHA/)
  assert.throws(() => compositeColor('url(https://example.invalid)'), /INVALID_REFERENCE_COLOR/)
})

test('VS2026 exact generated exemption cannot conceal feature literals or generated tampering', async () =>
  fixture(async ({ directory, put }) => {
    for (const folder of featureRoots) await mkdir(resolve(directory, folder), { recursive: true })
    await put(
