export async function generateReference(base = root) {
  const files = {},
    manifest = []
  for (const [name, expected] of Object.entries(expectedSources)) {
    const bytes = await readFile(resolve(base, referenceDirectory, 'upstream', name))
    if (digest(bytes) !== expected) throw Error('REFERENCE_SOURCE_DRIFT:' + name)
    files[name] = bytes.toString('utf8')
    manifest.push({ name, sha256: expected, bytes: bytes.length })
  }
  const actualAttributes = (
    await readFile(resolve(base, referenceDirectory, '.gitattributes'), 'utf8')
  ).replaceAll('\r\n', '\n')
  if (actualAttributes !== attributes) throw Error('REFERENCE_CHECKOUT_ATTRIBUTE_DRIFT')
  const merged = parseSourceClosure(files)
  const builtin = JSON.parse(
    await readFile(resolve(base, 'packages/ui-workspace/tokens/tokens.json'), 'utf8'),
  )
  const colors = {},
    mappings = [],
    repairs = []
  for (const role of Object.keys(builtin.themes.dark)) {
    const keys = roleMap[role],
      original = keys ? merged.colors[keys[0]] : undefined
    colors[role] = original
      ? compositeColor(original, keys[1] ? merged.colors[keys[1]] : undefined)
      : builtin.themes.dark[role]
    mappings.push({
      role,
      key: keys?.[0] ?? null,
      original: original ?? null,
      mapped: colors[role],
      source: original ? 'UPSTREAM' : 'FRADE_NO_COUNTERPART',
    })
  }
  // This build-time palette adaptation preserves upstream surfaces. The runtime's
  // existing fixed-pair validator/repair remains unchanged and still validates it.
  for (const foreground of [...new Set(contrastPairs.map((pair) => pair[0]))]) {
    const pairs = contrastPairs.filter((pair) => pair[0] === foreground)
    const passes = (color) =>
      pairs.every(([, background, minimum]) => contrastRatio(color, colors[background]) >= minimum)
    if (passes(colors[foreground])) continue
    const original = colors[foreground],
      raw = roleMap[foreground] ? merged.colors[roleMap[foreground][0]] : undefined
    const candidates = [
      raw?.length === 9 ? raw.slice(0, 7) : undefined,
      builtin.themes.dark[foreground],
      merged.colors['checkbox.foreground'],
      builtin.themes.dark['text.secondary'],
      builtin.themes.dark['text.primary'],
      builtin.themes.light['text.primary'],
    ].filter(Boolean)
    const replacement = candidates.find(passes)
    if (!replacement) throw Error('REFERENCE_CONTRAST_UNRESOLVED:' + foreground)
    colors[foreground] = replacement
    repairs.push({
      role: foreground,
      original,
      effective: replacement,
      reason: 'NAMED_CONTRAST_PAIR_FOREGROUND_ADAPTATION',
    })
  }
  if (contrastPairs.some(([fg, bg, minimum]) => contrastRatio(colors[fg], colors[bg]) < minimum))
    throw Error('REFERENCE_CONTRAST_INVALID')
  const slotData = Object.fromEntries(
    Object.entries(slots).map(([name, [key, role, background, minimum]]) => {
      const raw = merged.colors[key] ?? colors[role]
      if (typeof raw !== 'string' || !/^#[a-f\d]{3,8}$/i.test(raw))
        throw Error('INVALID_REFERENCE_SLOT:' + key)
      return [
        name,
        { key, role, raw, ...(background ? { background } : {}), ...(minimum ? { minimum } : {}) },
      ]
    }),
  )
  const mappedKeys = new Set([
    ...Object.values(roleMap).flat(),
    ...Object.values(slots).map((slot) => slot[0]),
  ])
  const data = {
    id: themeId,
    label: 'VS Code Dark 2026',
    kind: 'dark',
    descriptor: { id: themeId, label: 'VS Code Dark 2026', kind: 'dark', colors },
    slots: slotData,
    provenance: {
      repository: 'https://github.com/microsoft/vscode',
      commit: '36e19389b8a2e64498d0d4d860c346424bf90a3a',
      manifest,
    },
    compatibility: {
      mappings,
      repairs,
      namedContrastPairs: contrastPairs.length,
      colors: Object.keys(merged.colors)
        .sort()
        .map((key) => ({
          key,
          status: mappedKeys.has(key) ? 'MAPPED_OR_COMPOSED' : 'RETAINED_ONLY_NO_FRADE_COUNTERPART',
        })),
      syntaxRules: merged.tokenColors.length,
      semanticRules: Object.keys(merged.semanticTokenColors).length,

      semanticRules: Object.keys(merged.semanticTokenColors).length,
      syntaxConsumer: 'NOT_IMPLEMENTED_RETAINED_ONLY',
      geometryDeviations: [
        'canonical row minima28/36',
        'status target minimum24',
        'default tab-height referenceNOT_CONFIRMED; existing35 retained',
      ],
    },
    upstreamSources: files,
  }
  const license = files['LICENSE.txt'].replaceAll('*/', '* /')
  return (
    '/*! Microsoft VS Code source, MIT license; retained verbatim below.\n' +
    license +
    '\n*/\n' +
    '// Generated by scripts/ui/vscode-dark-2026.mjs; do not edit.\n' +
    'export const referenceTheme = ' +
    JSON.stringify(data, null, 2) +
    ' as const\n'
  )
}

export async function checkReferenceFiles(base = root, write = false) {
  try {
    const output = await generateReference(base)
    if (write) {
      await mkdir(dirname(resolve(base, generatedPath)), { recursive: true })
      await writeFile(resolve(base, generatedPath), output)
    }
    const actual = await readFile(resolve(base, generatedPath), 'utf8')
    return {
      status: actual === output ? 'PASS' : 'FAIL',
      errors: actual === output ? [] : ['REFERENCE_GENERATED_DRIFT'],
    }
  } catch (error) {
    return { status: 'FAIL', errors: [String(error)] }
  }
}
export function expectedReferenceAttributes() {
  return attributes
}
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const base = process.argv.includes('--root')
    ? resolve(process.argv[process.argv.indexOf('--root') + 1])
    : root
  const result = await checkReferenceFiles(base, process.argv.includes('--write'))
  console.log(JSON.stringify(result))
  process.exitCode = result.status === 'PASS' ? 0 : 1
}

